    void start() {
        this->template open_port<typename ActorBase::ports::AlertSkeleton1>();
        this->template open_port<typename ActorBase::ports::AlertSkeleton2>();
        this->template open_port<typename ActorBase::ports::AlertSkeleton3>();
        this->template open_port<typename ActorBase::ports::SupervisorOut>();
        this->template open_port<typename ActorBase::ports::PrimaryBody>();
        this->template open_port<typename ActorBase::ports::PrimarySupervisor>();
        this->template open_port<typename ActorBase::ports::SecondaryBody>();
        this->template open_port<typename ActorBase::ports::SecondarySupervisor>();
        this->template open_port<typename ActorBase::ports::SensorFlushPort>();
    }

    void stop() {
        this->template close_port<typename ActorBase::ports::AlertSkeleton1>();
        this->template close_port<typename ActorBase::ports::AlertSkeleton2>();
        this->template close_port<typename ActorBase::ports::AlertSkeleton3>();
        this->template close_port<typename ActorBase::ports::SupervisorOut>();
        this->template close_port<typename ActorBase::ports::PrimaryBody>();
        this->template close_port<typename ActorBase::ports::PrimarySupervisor>();
        this->template close_port<typename ActorBase::ports::SecondaryBody>();
        this->template close_port<typename ActorBase::ports::SecondarySupervisor>();
        this->template close_port<typename ActorBase::ports::SensorFlushPort>();
    }

